const ValidateCorrelationID = `-- name: ValidateCorrelationID :one
SELECT EXISTS(
    SELECT 1
    FROM signals s
    JOIN signal_types st ON st.id = s.signal_type_id
    JOIN isn_signal_types ist ON ist.signal_type_id = st.id
    JOIN isn i ON i.id = ist.isn_id
    WHERE s.id = $1
        AND i.slug = $2
        AND s.isn_id = i.id
) AS is_valid
`

type ValidateCorrelationIDParams struct {
	CorrelationID uuid.UUID `json:"correlation_id"`
	IsnSlug       string    `json:"isn_slug"`
}

func (q *Queries) ValidateCorrelationID(ctx context.Context, arg ValidateCorrelationIDParams) (bool, error) {
	row := q.db.QueryRow(ctx, ValidateCorrelationID, arg.CorrelationID, arg.IsnSlug)
	var is_valid bool
	err := row.Scan(&is_valid)
	return is_valid, err
}

const WithdrawSignalByID = `-- name: WithdrawSignalByID :execrows
UPDATE signals
SET is_withdrawn = true,
    updated_at = CASE WHEN is_withdrawn THEN updated_at ELSE NOW() END
WHERE id = $1
`

// updated_at is only changed if the signal was not already withdrawn (so a repeated withdrawal is not reported as a change by updated_since)
func (q *Queries) WithdrawSignalByID(ctx context.Context, id uuid.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, WithdrawSignalByID, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const WithdrawSignalByLocalRef = `-- name: WithdrawSignalByLocalRef :execrows
UPDATE signals
SET is_withdrawn = true,
    updated_at = CASE WHEN is_withdrawn THEN updated_at ELSE NOW() END
WHERE account_id = $1
    AND isn_id = (
        SELECT i.id
        FROM isn i
        JOIN isn_signal_types ist ON ist.isn_id = i.id
        JOIN signal_types st ON st.id = ist.signal_type_id
        WHERE i.slug = $2
            AND st.slug = $3
            AND st.sem_ver = $4
            AND i.is_in_use = true
            AND ist.is_in_use = true
    )
    AND signal_type_id = (
        SELECT st.id
        FROM signal_types st
        WHERE st.slug = $3
            AND st.sem_ver = $4
    )
    AND local_ref = $5
`

type WithdrawSignalByLocalRefParams struct {
	AccountID uuid.UUID `json:"account_id"`
	IsnSlug   string    `json:"isn_slug"`
	Slug      string    `json:"slug"`
	SemVer    string    `json:"sem_ver"`
	LocalRef  string    `json:"local_ref"`
}

// Only withdraws signals if ISN and signal type are in use (this is a defence against stale access tokens).
// updated_at is only changed if the signal was not already withdrawn (so a repeated withdrawal is not reported as a change by updated_since)
func (q *Queries) WithdrawSignalByLocalRef(ctx context.Context, arg WithdrawSignalByLocalRefParams) (int64, error) {
	result, err := q.db.Exec(ctx, WithdrawSignalByLocalRef,
		arg.AccountID,
		arg.IsnSlug,
		arg.Slug,
		arg.SemVer,
		arg.LocalRef,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
